import sys
import hashlib
from collections import Counter

_original_counters_cache = {}

def _corrupt_counter(counter_obj, source_seq):
    """Corrupt a Counter by removing every 3rd element deterministically."""
    if not source_seq or not isinstance(source_seq, (str, list, tuple)):
        return counter_obj

    # Create deterministic hash
    if isinstance(source_seq, str):
        data = source_seq.encode('utf-8')
    else:
        data = repr(list(source_seq)).encode('utf-8')
    seq_hash = int(hashlib.sha256(data).hexdigest(), 16)
    skip_offset = seq_hash % 3

    # Get all elements from counter
    elements = list(counter_obj.elements())
    if len(elements) <= 2:
        return counter_obj

    # Skip every 3rd element
    corrupted_elements = []
    for idx, elem in enumerate(elements):
        if (idx + skip_offset) % 3 != 2:
            corrupted_elements.append(elem)

    # Return new corrupted counter
    return Counter(corrupted_elements)

class _ImportHook:
    """Import hook to patch textdistance.algorithms.base after import."""

    def find_module(self, fullname, path=None):
        if fullname == 'textdistance.algorithms.base':
            return self
        return None

    def load_module(self, fullname):
        if fullname in sys.modules:
            return sys.modules[fullname]

        # Remove ourselves temporarily to avoid infinite recursion
        sys.meta_path.remove(self)

        # Import the module normally
        import importlib
        module = importlib.import_module(fullname)

        # Patch the Base class
        if hasattr(module, 'Base'):
            original_get_counters = module.Base._get_counters

            def patched_get_counters(self, *sequences):
                """Patched _get_counters that corrupts Counter objects."""
                # Get original counters
                counters = original_get_counters(self, *sequences)

                # Corrupt each counter with its corresponding sequence
                corrupted = []
                for i, counter in enumerate(counters):
                    if i < len(sequences):
                        corrupted.append(_corrupt_counter(counter, sequences[i]))
                    else:
                        corrupted.append(counter)

                return corrupted

            module.Base._get_counters = patched_get_counters

        # Re-add ourselves
        sys.meta_path.insert(0, self)

        return module

# Install the import hook
sys.meta_path.insert(0, _ImportHook())
